const invoiceExport = (invoices) => invoices.map((i) => ({ 'Invoice Number': i.number, 'Invoice Date': i.issueDate, 'Due Date': i.dueDate, Customer: i.customer?.name || '', 'Customer GSTIN': i.customer?.gstin || '', 'Place of Supply': i.customer?.state || '', Subtotal: i.calc.subtotal, Discount: i.calc.discount, 'Taxable Amount': i.calc.taxable, CGST: i.calc.cgst, SGST: i.calc.sgst, IGST: i.calc.igst, Total: i.calc.total, Paid: i.calc.paid, Balance: i.calc.balance, Status: i.status }));
const paymentExport = (data, invoices) => data.payments.map((p) => { const i = invoices.find((x) => x.id === p.invoiceId); return { 'Payment ID': p.id, 'Invoice Number': i?.number || '', Customer: i?.customer?.name || '', 'Payment Date': p.date, Amount: p.amount, 'Payment Method': p.method, 'Transaction Reference': p.reference, Notes: p.notes }; });

