function calculate(invoice) {
  const lineAmount = (item) => item.amount !== undefined && item.amount !== '' ? Number(item.amount || 0) : Number(item.qty || 0) * Number(item.rate || 0);
  const subtotal = (invoice.items || []).reduce((sum, item) => sum + lineAmount(item), 0);
  const discount = Math.min(Number(invoice.discount || 0), subtotal);
  const taxable = subtotal - discount;
  const tax = (invoice.items || []).reduce((sum, item) => sum + lineAmount(item) * (Number(item.gst || 0) / 100), 0) * (subtotal ? taxable / subtotal : 1);
  const sameState = invoice.customerStateCode === '32';
  const paid = Number(invoice.paid || 0);
  return { subtotal, discount, taxable, tax, cgst: sameState ? tax / 2 : 0, sgst: sameState ? tax / 2 : 0, igst: sameState ? 0 : tax, total: taxable + tax, paid, balance: Math.max(0, taxable + tax - paid) };
}

function useStore() {
  const [data, setData] = useState(() => { try { return JSON.parse(localStorage.getItem('ellext-billing-data')) || seed; } catch { return seed; } });
  useEffect(() => localStorage.setItem('ellext-billing-data', JSON.stringify(data)), [data]);
  const update = (key, value) => setData((d) => ({ ...d, [key]: value }));
  return { data, update, setData };
}

function Logo({ compact = false }) { return <div className={`logo-lockup ${compact ? 'compact' : ''}`}><img src={logo} alt="Ellext Marketing" /><span>Billing workspace</span></div>; }

