      <div className="page-wrap">{page === 'Dashboard' && <Dashboard invoices={invoiceRows} data={store.data} onOpen={setSelectedInvoice} onCreate={() => go('Create Invoice')} />}{page === 'Invoices' && <Invoices invoices={invoiceRows} data={store.data} update={store.update} onOpen={setSelectedInvoice} onCreate={() => go('Create Invoice')} notify={notify} />}{page === 'Create Invoice' && <InvoiceForm data={store.data} update={store.update} onBack={() => go('Invoices')} onSaved={(inv) => { notify('Invoice saved successfully'); setSelectedInvoice(inv); go('Invoices'); }} onPreview={setSelectedInvoice} />}{page === 'Customers' && <CustomersV2 data={store.data} update={store.update} notify={notify} />}{page === 'Services' && <ServicesV2 data={store.data} update={store.update} notify={notify} />}{page === 'Payments' && <Payments data={store.data} invoices={invoiceRows} update={store.update} notify={notify} />}{page === 'Reports' && <Reports data={store.data} invoices={invoiceRows} />}{page === 'Backup' && <BackupV2 data={store.data} setData={store.setData} notify={notify} invoices={invoiceRows} />}{page === 'Settings' && <Settings data={store.data} update={store.update} notify={notify} />}</div>
