function LegacyAuthGate({ children }) {
  const api = import.meta.env.VITE_API_URL || '/api'; const [state, setState] = useState('checking'); const [mode, setMode] = useState('login'); const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [challengeId, setChallengeId] = useState(''); const [maskedEmail, setMaskedEmail] = useState(''); const [otp, setOtp] = useState(['', '', '', '', '', '']); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  useEffect(() => { fetch(`${api}/auth/me`, { credentials: 'include' }).then((response) => { setState(response.ok ? 'authenticated' : 'login'); }).catch(() => setState('login')); const logout = () => setState('login'); window.addEventListener('ellext-auth-logout', logout); return () => window.removeEventListener('ellext-auth-logout', logout); }, [api]);
  const submitLogin = async (event) => { event.preventDefault(); setBusy(true); setError(''); try { const response = await fetch(`${api}/auth/login`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include', body: JSON.stringify({ email, password }) }); const payload = await response.json(); if (!response.ok) throw new Error(payload.error?.message || payload.message || 'Unable to sign in.'); setChallengeId(payload.data.challengeId); setMaskedEmail(payload.data.maskedEmail); setMode('verify'); } catch (err) { setError(err.message); } finally { setBusy(false); } };
  const submitVerify = async (event) => { event.preventDefault(); setBusy(true); setError(''); try { const response = await fetch(`${api}/auth/verify-code`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include', body: JSON.stringify({ challengeId, code: otp.join('') }) }); const payload = await response.json(); if (!response.ok) throw new Error(payload.error?.message || 'The code is invalid or expired.'); setState('authenticated'); } catch (err) { setError(err.message); } finally { setBusy(false); } };
  const resend = async () => { setBusy(true); setError(''); try { const response = await fetch(`${api}/auth/resend-code`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include', body: JSON.stringify({ challengeId }) }); const payload = await response.json(); if (!response.ok) throw new Error(payload.error?.message || 'We could not resend the code.'); setError('A new verification code was sent.'); } catch (err) { setError(err.message); } finally { setBusy(false); } };
  const forgot = async (event) => { event.preventDefault(); setBusy(true); setError(''); try { await fetch(`${api}/auth/forgot-password`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ email }) }); setError("If the account exists, we've sent password reset instructions."); setMode('login'); } catch { setError('Something went wrong. Please try again.'); } finally { setBusy(false); } };
  const changeOtp = (index, value) => { const digits = value.replace(/\D/g, '').slice(-6); if (digits.length > 1) { setOtp(digits.split('').concat(['', '', '', '', '', '']).slice(0, 6)); return; } const next = [...otp]; next[index] = digits; setOtp(next); if (digits && index < 5) document.querySelector(`[data-otp="${index + 1}"]`)?.focus(); };
  const logout = async () => { await fetch(`${api}/auth/logout`, { method: 'POST', credentials: 'include' }).catch(() => null); setState('login'); setMode('login'); setPassword(''); setOtp(['', '', '', '', '', '']); };
  if (state === 'checking') return <div className="auth-screen"><div className="auth-card"><div className="auth-brand"><img src={logo} alt="Ellext Marketing" /></div><p>Checking your secure session…</p></div></div>;
  if (state === 'authenticated') return <><button className="auth-logout" onClick={logout}>Logout</button>{children}</>;
  return <div className="auth-screen"><section className="auth-card"><div className="auth-brand"><img src={logo} alt="Ellext Marketing" /><small>Ellext Marketing Billing</small></div>{mode === 'login' && <><h1>Sign in</h1><p>Use your Ellext Marketing account to continue.</p><form className="auth-form" onSubmit={submitLogin}><label>Email<input type="email" autoComplete="email" value={email} onChange={(e) => setEmail(e.target.value)} required /></label><label>Password<input type="password" autoComplete="current-password" value={password} onChange={(e) => setPassword(e.target.value)} required /></label>{error && <div className="auth-error">{error}</div>}<button className="button primary auth-submit" disabled={busy}>{busy ? 'Please wait…' : 'Continue'}</button><button className="auth-link" type="button" onClick={() => { setMode('forgot'); setError(''); }}>Forgot password?</button></form></>}{mode === 'forgot' && <><h1>Reset password</h1><p>Enter your email and we’ll send instructions if the account exists.</p><form className="auth-form" onSubmit={forgot}><label>Email<input type="email" autoComplete="email" value={email} onChange={(e) => setEmail(e.target.value)} required /></label>{error && <div className="auth-error">{error}</div>}<button className="button primary auth-submit" disabled={busy}>Send instructions</button><button className="auth-back" type="button" onClick={() => { setMode('login'); setError(''); }}>Back to sign in</button></form></>}{mode === 'verify' && <><h1>Verify your email</h1><p>Enter the 6-digit code sent to {maskedEmail}.</p><form className="auth-form" onSubmit={submitVerify}><div className="otp-grid">{otp.map((digit, index) => <input key={index} data-otp={index} inputMode="numeric" maxLength="6" value={digit} onChange={(e) => changeOtp(index, e.target.value)} onKeyDown={(e) => { if (e.key === 'Backspace' && !otp[index] && index > 0) document.querySelector(`[data-otp="${index - 1}"]`)?.focus(); }} aria-label={`Verification digit ${index + 1}`} required />)}</div>{error && <div className="auth-error">{error}</div>}<button className="button primary auth-submit" disabled={busy || otp.join('').length !== 6}>{busy ? 'Verifying…' : 'Verify & Continue'}</button><button className="auth-link" type="button" onClick={resend} disabled={busy}>Resend code</button><button className="auth-back" type="button" onClick={() => { setMode('login'); setError(''); }}>Back to sign in</button></form></>}</section></div>;
}

function LiveUserLabels({ user }) {
  useEffect(() => {
    if (!user) return;
    const name = user.full_name?.trim() || user.email?.split('@')[0] || 'User';
    const firstName = name.split(/\s+/)[0];
    const initials = name.split(/\s+/).filter(Boolean).slice(0, 2).map((part) => part[0]).join('').toUpperCase() || 'U';
    document.querySelectorAll('.user-row strong').forEach((node) => { node.textContent = name; });
    document.querySelectorAll('.user-row small').forEach((node) => { node.textContent = user.role === 'ADMIN' ? 'Administrator' : 'Staff'; });
    document.querySelectorAll('.avatar, .top-avatar').forEach((node) => { node.textContent = initials; });
    document.querySelectorAll('.page-header h1').forEach((node) => { if (node.textContent?.includes('Arjun')) node.textContent = `Good morning, ${firstName}`; });
  }, [user]);
  return null;
}

function AuthGate({ children }) {
  const api = import.meta.env.VITE_API_URL || '/api';
  const [state, setState] = useState('checking');
  const [mode, setMode] = useState('login');
  const [email, setEmail] = useState('');
  const [name, setName] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [challengeId, setChallengeId] = useState('');
  const [maskedEmail, setMaskedEmail] = useState('');
  const [otp, setOtp] = useState(['', '', '', '', '', '']);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  const [busy, setBusy] = useState(false);
  const [currentUser, setCurrentUser] = useState(null);

  useEffect(() => {
    fetch(`${api}/auth/me`, { credentials: 'include' })
      .then(async (response) => { if (!response.ok) { setState('login'); return; } const payload = await response.json().catch(() => ({})); setCurrentUser(payload.data?.user || null); setState('authenticated'); })
      .catch(() => setState('login'));
    const logout = () => setState('login');
    window.addEventListener('ellext-auth-logout', logout);
    return () => window.removeEventListener('ellext-auth-logout', logout);
  }, [api]);

  const showMode = (nextMode) => {
    setMode(nextMode);
    setError('');
    setNotice('');
    setOtp(['', '', '', '', '', '']);
  };

  const readError = async (response, fallback) => {
    const payload = await response.json().catch(() => ({}));
    const message = payload.error?.message || payload.message || fallback;
    if (response.status === 404) return 'The billing API signup route is unavailable. Restart the API server and try again.';
    if (response.status >= 500 && !payload.error?.message && !payload.message) return 'The billing API is unavailable on Vercel. Add the required environment variables to the Vercel project and redeploy.';
    if (payload.error?.code === 'SIGNUP_FAILED' && message === 'We could not create the account. Please try again.') return 'The API server is using an older version. Restart the billing API and refresh this page.';
    return message;
  };

  const startVerification = (payload) => {
    setChallengeId(payload.data.challengeId);
    setMaskedEmail(payload.data.maskedEmail);
    setOtp(['', '', '', '', '', '']);
    setMode('verify');
  };

  const submitLogin = async (event) => {
    event.preventDefault();
    setBusy(true);
    setError('');
    setNotice('');
    try {
      const response = await fetch(`${api}/auth/login`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include', body: JSON.stringify({ email, password }) });
      if (!response.ok) throw new Error(await readError(response, 'Unable to sign in.'));
      const payload = await response.json();
      setCurrentUser(payload.data?.user || null);
      setState('authenticated');
    } catch (err) { setError(err.message); } finally { setBusy(false); }
  };

  const submitSignup = async (event) => {
    event.preventDefault();
    if (password !== confirmPassword) { setError('Passwords do not match.'); return; }
    setBusy(true);
    setError('');
    try {
      const response = await fetch(`${api}/auth/signup`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include', body: JSON.stringify({ name, email, password, confirmPassword }) });
      if (!response.ok) throw new Error(await readError(response, 'Unable to create the account.'));
      const payload = await response.json();
      setPassword('');
      setConfirmPassword('');
      setMode('login');
      setNotice(payload.data?.message || 'Account created. Sign in with your email and password.');
    } catch (err) { setError(err.message); } finally { setBusy(false); }
  };

  const submitVerify = async (event) => {
    event.preventDefault();
    setBusy(true);
    setError('');
    try {
      const response = await fetch(`${api}/auth/verify-code`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include', body: JSON.stringify({ challengeId, code: otp.join('') }) });
      if (!response.ok) throw new Error(await readError(response, 'The code is invalid or expired.'));
      setState('authenticated');
    } catch (err) { setError(err.message); } finally { setBusy(false); }
  };

  const resend = async () => {
    setBusy(true);
    setError('');
    try {
      const response = await fetch(`${api}/auth/resend-code`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include', body: JSON.stringify({ challengeId }) });
      if (!response.ok) throw new Error(await readError(response, 'We could not resend the code.'));
      setError('A new verification code was sent to your email.');
    } catch (err) { setError(err.message); } finally { setBusy(false); }
  };

  const forgot = async (event) => {
    event.preventDefault();
    setBusy(true);
    setError('');
    try {
      await fetch(`${api}/auth/forgot-password`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ email }) });
      setError("If the account exists, we've sent password reset instructions.");
    } catch { setError('Something went wrong. Please try again.'); } finally { setBusy(false); }
  };

  const changeOtp = (index, value) => {
    const digits = value.replace(/\D/g, '');
    if (digits.length > 1) {
      setOtp(digits.slice(0, 6).split('').concat(['', '', '', '', '', '']).slice(0, 6));
      return;
    }
    const next = [...otp];
    next[index] = digits;
    setOtp(next);
    if (digits && index < 5) document.querySelector(`[data-otp="${index + 1}"]`)?.focus();
  };

  const logout = async () => {
    await fetch(`${api}/auth/logout`, { method: 'POST', credentials: 'include' }).catch(() => null);
    setCurrentUser(null);
    setState('login');
    showMode('login');
    setPassword('');
  };

  if (state === 'checking') return <div className="auth-screen"><div className="auth-card"><div className="auth-brand"><img src={logo} alt="Ellext Marketing" /></div><p>Checking your secure session…</p></div></div>;
  if (state === 'authenticated') return <><LiveUserLabels user={currentUser} /><button className="auth-logout" onClick={logout}>Logout</button>{children}</>;

  return <div className="auth-screen"><section className="auth-card"><div className="auth-brand"><img src={logo} alt="Ellext Marketing" /><small>Ellext Marketing Billing</small></div>
    {mode === 'login' && <><h1>Sign in</h1><p>Use your Ellext Marketing account to continue.</p><form className="auth-form" onSubmit={submitLogin}><label>Email<input type="email" autoComplete="email" value={email} onChange={(e) => setEmail(e.target.value)} required /></label><label>Password<input type="password" autoComplete="current-password" value={password} onChange={(e) => setPassword(e.target.value)} required /></label>{notice && <div className="auth-success">{notice}</div>}{error && <div className="auth-error">{error}</div>}<button className="button primary auth-submit" disabled={busy}>{busy ? 'Please wait…' : 'Sign in'}</button><div className="auth-actions"><button className="auth-link" type="button" onClick={() => showMode('forgot')}>Forgot password?</button><button className="auth-link" type="button" onClick={() => showMode('signup')}>Create an account</button></div></form></>}
    {mode === 'signup' && <><h1>Create account</h1><p>Create your billing workspace account. After creating it, sign in with your email and password.</p><form className="auth-form" onSubmit={submitSignup}><label>Full name<input type="text" autoComplete="name" value={name} onChange={(e) => setName(e.target.value)} required /></label><label>Email<input type="email" autoComplete="email" value={email} onChange={(e) => setEmail(e.target.value)} required /></label><label>Password<input type="password" autoComplete="new-password" value={password} onChange={(e) => setPassword(e.target.value)} minLength="8" required /><small className="auth-hint">Use at least 8 characters with upper/lowercase, a number, and a symbol.</small></label><label>Confirm password<input type="password" autoComplete="new-password" value={confirmPassword} onChange={(e) => setConfirmPassword(e.target.value)} minLength="8" required /></label>{error && <div className="auth-error">{error}</div>}<button className="button primary auth-submit" disabled={busy}>{busy ? 'Creating account…' : 'Sign up'}</button><button className="auth-back" type="button" onClick={() => showMode('login')}>Already have an account? Sign in</button></form></>}
    {mode === 'forgot' && <><h1>Reset password</h1><p>Enter your email and we’ll send instructions if the account exists.</p><form className="auth-form" onSubmit={forgot}><label>Email<input type="email" autoComplete="email" value={email} onChange={(e) => setEmail(e.target.value)} required /></label>{error && <div className="auth-error">{error}</div>}<button className="button primary auth-submit" disabled={busy}>Send instructions</button><button className="auth-back" type="button" onClick={() => showMode('login')}>Back to sign in</button></form></>}
  </section></div>;
}

function App() { return <AuthGate><BillingApp /></AuthGate>; }
window.addEventListener('go-invoices', () => { /* navigation is handled by the shell on next render */ });
createRoot(document.getElementById('root')).render(<App />);
